# Check if rlm is accessible as a Python variable or module
try:
    from __main__ import rlm
    print("rlm found in __main__")
except ImportError:
    print("rlm not in __main__")

# Check globals
print("Globals keys:", [k for k in globals().keys() if 'rlm' in k.lower() or 'finish' in k.lower()])

# Try importing from various places
for mod_path in ['rlm', 'tools.rlm', 'world.rlm']:
    try:
        m = __import__(mod_path.replace('.', '.__').replace('..', '.'), fromlist=[''])
        print(f"Imported {mod_path}: {m}")
    except Exception as e:
        print(f"Failed to import {mod_path}: {e}")
